<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> accuracy</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">y_hat</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">y</span><span style="color:#ABB2BF;">):</span></span>
